import pcbnew,json,hashlib,sys
b=pcbnew.LoadBoard(sys.argv[1]);tracks=[]
for t in b.GetTracks():
 if t.GetClass()=='PCB_VIA':tracks.append(['via',t.GetNetname(),t.GetPosition().x,t.GetPosition().y,t.GetWidth(),t.GetDrillValue()])
 else:
  a,c=t.GetStart(),t.GetEnd();ends=sorted([(a.x,a.y),(c.x,c.y)]);tracks.append(['track',t.GetNetname(),b.GetLayerName(t.GetLayer()),ends,t.GetWidth()])
parts=[]
for f in b.GetFootprints():
 pads=sorted([[p.GetNumber(),p.GetNetname(),p.GetPosition().x,p.GetPosition().y,p.GetSize().x,p.GetSize().y] for p in f.Pads()])
 parts.append([f.GetReference(),f.GetPosition().x,f.GetPosition().y,f.GetOrientationDegrees(),b.GetLayerName(f.GetLayer()),pads])
data={'tracks':sorted(tracks,key=lambda x:json.dumps(x)),'parts':sorted(parts)}
print(json.dumps({'sha256':hashlib.sha256(json.dumps(data,sort_keys=True,separators=(',',':')).encode()).hexdigest(),'tracks_and_vias':len(tracks),'footprints':len(parts),'pcbnew':pcbnew.GetBuildVersion()}))
